export const statuses = [
  'Ready',
  'Building',
  'Queued',
  'Error',
  'Canceled',
] as const
export const environments = ['Production', 'Preview'] as const

export type DeploymentStatus = (typeof statuses)[number]
export type Environment = (typeof environments)[number]

export type Deployment = {
  id: string
  status: DeploymentStatus
  environment: Environment
  branch: string
  sha: string
  message: string
  author: string
  /** Epoch ms */
  createdAt: number
  /** Build time in seconds; null while still queued */
  durationSec: number | null
}

// Fixed "now" so relative times render the same on server and client.
export const NOW = Date.UTC(2026, 8, 23, 14, 0, 0)

const MIN = 60_000

// Small deterministic PRNG, so the demo data never changes between renders.
function mulberry32(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const random = mulberry32(7)
const pick = <T>(items: readonly T[]) =>
  items[Math.floor(random() * items.length)]

const branches = [
  'main',
  'main',
  'main',
  'feat/billing-v2',
  'fix/login-redirect',
  'chore/deps',
  'feat/search',
]
const authors = ['ava', 'liam', 'sofia', 'noah', 'mia']
const messages = [
  'Add usage-based billing tiers',
  'Fix redirect loop after SSO login',
  'Bump dependencies',
  'Cache search results at the edge',
  'Tighten CSP headers',
  'Move pricing page to ISR',
  'Handle empty cart in checkout',
  'Improve cold start time',
  'Refactor auth middleware',
  'Add OpenGraph images',
  'Fix flaky e2e test',
  'Update onboarding copy',
]

function hexSha() {
  return Array.from({ length: 7 }, () =>
    Math.floor(random() * 16).toString(16),
  ).join('')
}

function statusFor(index: number): DeploymentStatus {
  // Newest two are still in flight, like a real deploy list
  if (index === 0) return 'Building'
  if (index === 1) return 'Queued'
  const roll = random()
  if (roll < 0.72) return 'Ready'
  if (roll < 0.86) return 'Error'
  return 'Canceled'
}

let minutesAgo = 2
export const deployments: Deployment[] = Array.from({ length: 42 }, (_, i) => {
  const branch = pick(branches)
  const status = statusFor(i)
  const createdAt = NOW - minutesAgo * MIN
  // Gaps grow with age, so the list spans roughly a month
  minutesAgo += Math.floor(8 + random() * 40 + i * i * 0.9)
  return {
    id: `dpl_${hexSha()}${hexSha().slice(0, 3)}`,
    status,
    environment: branch === 'main' ? 'Production' : 'Preview',
    branch,
    sha: hexSha(),
    message: pick(messages),
    author: pick(authors),
    createdAt,
    durationSec:
      status === 'Queued'
        ? null
        : status === 'Building'
          ? 42
          : Math.floor(35 + random() * 200),
  }
})

/** Latest successful production deploy — the one serving traffic */
export const currentProductionId = deployments.find(
  (d) => d.environment === 'Production' && d.status === 'Ready',
)?.id

export function formatAge(createdAt: number): string {
  const minutes = Math.round((NOW - createdAt) / MIN)
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.round(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  return `${Math.round(hours / 24)}d ago`
}

export function formatDuration(seconds: number): string {
  const m = Math.floor(seconds / 60)
  const s = seconds % 60
  return m ? `${m}m ${s}s` : `${s}s`
}

'use client'

import type { ColumnDef, FilterFn } from '@tanstack/react-table'
import { GitBranch, GitCommitHorizontal } from 'lucide-react'
import { cn } from '#/lib/utils.ts'
import { NOW, currentProductionId, formatAge, formatDuration } from './data'
import type { Deployment, DeploymentStatus } from './data'

const statusDot: Record<Exclude<DeploymentStatus, 'Queued'>, string> = {
  Ready: 'bg-emerald-500',
  Building: 'bg-amber-500 motion-safe:animate-pulse',
  Error: 'bg-red-500',
  Canceled: 'bg-muted-foreground/30',
}

/**
 * Status marker, shared by the table and the Status filter menu. Queued gets
 * a spinning ring instead of a dot, so "waiting for a builder" reads as
 * activity rather than as a dead grey state.
 */
export function StatusIcon({ status }: { status: DeploymentStatus }) {
  if (status === 'Queued') {
    return (
      <span
        aria-hidden
        className="size-2.5 shrink-0 rounded-full border-[1.5px] border-muted-foreground/30 border-t-muted-foreground motion-safe:animate-spin"
      />
    )
  }
  // Same 10px box as the ring, so labels line up whatever the status
  return (
    <span
      aria-hidden
      className="flex size-2.5 shrink-0 items-center justify-center"
    >
      <span className={cn('size-2 rounded-full', statusDot[status])} />
    </span>
  )
}

/** Stand-in for the build time while a deployment waits in the queue */
function QueuedIndicator() {
  return (
    <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
      <span className="sr-only">Waiting for a build slot</span>
      <span aria-hidden className="flex items-center gap-0.5">
        {[0, 150, 300].map((delay) => (
          <span
            key={delay}
            className="size-1 rounded-full bg-muted-foreground/60 motion-safe:animate-pulse"
            style={{ animationDelay: `${delay}ms` }}
          />
        ))}
      </span>
      <span aria-hidden>waiting</span>
    </span>
  )
}

// Multi-select filters store string[]; an empty/undefined value means "all"
const inList: FilterFn<Deployment> = (row, id, value: string[] | undefined) =>
  !value?.length || value.includes(row.getValue<string>(id))

// The date filter stores a number of days back from NOW
const withinDays: FilterFn<Deployment> = (row, id, days: number | undefined) =>
  days === undefined || row.getValue<number>(id) >= NOW - days * 86_400_000

export const columns: ColumnDef<Deployment>[] = [
  {
    accessorKey: 'id',
    header: 'Deployment',
    cell: ({ row }) => {
      const d = row.original
      return (
        <div className="space-y-1">
          <p className="font-mono text-xs">{d.id.slice(0, 13)}</p>
          <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
            {d.environment}
            {d.id === currentProductionId && (
              <span className="rounded-sm bg-sky-500/15 px-1 text-[11px] text-sky-700 dark:text-sky-300">
                Current
              </span>
            )}
          </p>
        </div>
      )
    },
  },
  {
    accessorKey: 'environment',
    filterFn: inList,
  },
  {
    accessorKey: 'status',
    header: 'Status',
    filterFn: inList,
    cell: ({ row }) => {
      const { status, durationSec } = row.original
      return (
        <div className="space-y-1">
          <p className="flex items-center gap-2">
            <StatusIcon status={status} />
            {status}
          </p>
          {durationSec === null ? (
            <QueuedIndicator />
          ) : (
            <p className="font-mono text-xs text-muted-foreground">
              {formatDuration(durationSec)}
            </p>
          )}
        </div>
      )
    },
  },
  {
    accessorKey: 'branch',
    header: 'Source',
    filterFn: inList,
    cell: ({ row }) => {
      const d = row.original
      return (
        <div className="min-w-0 max-w-72 space-y-1">
          <p className="flex items-center gap-1.5 truncate">
            <GitBranch className="size-3.5 shrink-0 text-muted-foreground" />
            <span className="truncate">{d.branch}</span>
          </p>
          <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <GitCommitHorizontal className="size-3.5 shrink-0" />
            <span className="font-mono">{d.sha}</span>
            <span className="truncate">{d.message}</span>
          </p>
        </div>
      )
    },
  },
  {
    accessorKey: 'createdAt',
    header: 'Created',
    filterFn: withinDays,
    cell: ({ row }) => (
      <div className="flex items-center justify-end gap-2 text-sm text-muted-foreground">
        <span className="tabular-nums">
          {formatAge(row.original.createdAt)}
        </span>
        <span>by {row.original.author}</span>
        <span
          aria-hidden
          className="flex size-6 items-center justify-center rounded-full bg-muted text-[11px] font-medium text-foreground uppercase"
        >
          {row.original.author.slice(0, 2)}
        </span>
      </div>
    ),
  },
  // Searchable text that isn't its own visible column
  { accessorKey: 'sha' },
  { accessorKey: 'message' },
  { accessorKey: 'author' },
]

/** Columns that exist only for filtering and search */
export const hiddenColumns = {
  environment: false,
  sha: false,
  message: false,
  author: false,
}

'use client'

import { Check, PlusCircle } from 'lucide-react'
import type { Column } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '#/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { cn } from '#/lib/utils.ts'

interface FacetedFilterProps<TData> {
  column: Column<TData> | undefined
  title: string
  options: readonly string[]
  /** Optional marker drawn before each option, e.g. a status dot */
  renderIcon?: (value: string) => React.ReactNode
}

/**
 * Multi-select column filter. Counts come from TanStack's faceting, which
 * applies every *other* active filter, so they always add up to what you'd
 * see after ticking that option.
 */
export function FacetedFilter<TData>({
  column,
  title,
  options,
  renderIcon,
}: FacetedFilterProps<TData>) {
  const counts = column?.getFacetedUniqueValues()
  const selected = new Set(
    (column?.getFilterValue() as string[] | undefined) ?? [],
  )

  function toggle(value: string) {
    const next = new Set(selected)
    if (next.has(value)) next.delete(value)
    else next.add(value)
    column?.setFilterValue(next.size ? [...next] : undefined)
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 border-dashed">
          <PlusCircle className="size-3.5" />
          {title}
          {selected.size > 0 && (
            <>
              <span className="mx-0.5 h-4 w-px bg-border" />
              {selected.size > 2 ? (
                <Badge
                  variant="secondary"
                  className="rounded-sm px-1 font-normal"
                >
                  {selected.size} selected
                </Badge>
              ) : (
                [...selected].map((value) => (
                  <Badge
                    key={value}
                    variant="secondary"
                    className="rounded-sm px-1 font-normal"
                  >
                    {value}
                  </Badge>
                ))
              )}
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-0" align="start">
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandEmpty>No results.</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.has(option)
                return (
                  <CommandItem key={option} onSelect={() => toggle(option)}>
                    <span
                      className={cn(
                        'flex size-4 items-center justify-center rounded-[4px] border',
                        isSelected
                          ? 'border-primary bg-primary text-primary-foreground'
                          : 'opacity-50',
                      )}
                    >
                      {isSelected && <Check className="size-3" />}
                    </span>
                    {renderIcon?.(option)}
                    <span className="truncate">{option}</span>
                    <span className="ml-auto font-mono text-xs text-muted-foreground">
                      {counts?.get(option) ?? 0}
                    </span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
            {selected.size > 0 && (
              <>
                <CommandSeparator />
                <CommandGroup>
                  <CommandItem
                    onSelect={() => column?.setFilterValue(undefined)}
                    className="justify-center text-center"
                  >
                    Clear filter
                  </CommandItem>
                </CommandGroup>
              </>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type {
  ColumnDef,
  ColumnFiltersState,
  FilterFn,
} from '@tanstack/react-table'
import { ChevronLeft, ChevronRight, Search, X } from 'lucide-react'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Button } from '#/components/ui/button'
import { Input } from '#/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils.ts'
import { StatusIcon, hiddenColumns } from './columns'
import { environments, statuses } from './data'
import type { Deployment, DeploymentStatus } from './data'
import { FacetedFilter } from './faceted-filter'

const datePresets = [
  { value: 'all', label: 'All time', days: undefined },
  { value: '1', label: 'Last 24 hours', days: 1 },
  { value: '7', label: 'Last 7 days', days: 7 },
  { value: '30', label: 'Last 30 days', days: 30 },
] as const

// Search matches the fields people actually paste: id, branch, sha, message, author
const searchDeployments: FilterFn<Deployment> = (row, _id, query: string) => {
  const q = query.trim().toLowerCase()
  if (!q) return true
  const d = row.original
  return [d.id, d.branch, d.sha, d.message, d.author].some((field) =>
    field.toLowerCase().includes(q),
  )
}

interface DeploymentsTableProps {
  columns: ColumnDef<Deployment, any>[]
  data: Deployment[]
}

export function DeploymentsTable({ columns, data }: DeploymentsTableProps) {
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([])
  const [globalFilter, setGlobalFilter] = useState('')

  const table = useReactTable({
    data,
    columns,
    getRowId: (row) => row.id,
    state: { columnFilters, globalFilter },
    onColumnFiltersChange: setColumnFilters,
    onGlobalFilterChange: setGlobalFilter,
    globalFilterFn: searchDeployments,
    // Filters should send the user back to page 1, not leave them on an empty page 4
    autoResetPageIndex: true,
    initialState: {
      columnVisibility: hiddenColumns,
      pagination: { pageSize: 10 },
    },
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    getPaginationRowModel: getPaginationRowModel(),
  })

  const envColumn = table.getColumn('environment')
  const dateColumn = table.getColumn('createdAt')
  const environment =
    (envColumn?.getFilterValue() as string[] | undefined)?.[0] ?? 'all'
  const days = dateColumn?.getFilterValue() as number | undefined
  const isFiltered = columnFilters.length > 0 || globalFilter !== ''

  function clearAll() {
    setColumnFilters([])
    setGlobalFilter('')
  }

  const filteredCount = table.getFilteredRowModel().rows.length
  const { pageIndex, pageSize } = table.getState().pagination

  return (
    <div className="space-y-3">
      {/* Row 1: search + result count. Row 2: filters. */}
      <div className="flex items-center gap-3">
        <div className="relative w-full sm:w-72">
          <Search className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={globalFilter}
            onChange={(e) => setGlobalFilter(e.target.value)}
            placeholder="Branch, commit, author…"
            aria-label="Search deployments"
            className="h-8 pl-8"
          />
        </div>
        <p
          className="ml-auto shrink-0 text-sm text-muted-foreground tabular-nums"
          aria-live="polite"
        >
          {filteredCount === data.length
            ? `${data.length} deployments`
            : `${filteredCount} of ${data.length}`}
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <Select
          value={environment}
          onValueChange={(value) =>
            envColumn?.setFilterValue(value === 'all' ? undefined : [value])
          }
        >
          <SelectTrigger
            size="sm"
            className="h-8 w-40"
            aria-label="Environment"
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All environments</SelectItem>
            {environments.map((env) => (
              <SelectItem key={env} value={env}>
                {env}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <FacetedFilter
          column={table.getColumn('status')}
          title="Status"
          options={statuses}
          renderIcon={(status) => (
            <StatusIcon status={status as DeploymentStatus} />
          )}
        />
        <FacetedFilter
          column={table.getColumn('branch')}
          title="Branch"
          options={[...new Set(data.map((d) => d.branch))].sort()}
        />

        <Select
          value={days === undefined ? 'all' : String(days)}
          onValueChange={(value) =>
            dateColumn?.setFilterValue(
              value === 'all' ? undefined : Number(value),
            )
          }
        >
          <SelectTrigger size="sm" className="h-8 w-36" aria-label="Date range">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {datePresets.map((preset) => (
              <SelectItem key={preset.value} value={preset.value}>
                {preset.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {isFiltered && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 px-2"
            onClick={clearAll}
          >
            Reset
            <X className="size-3.5" />
          </Button>
        )}
      </div>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    className={cn(
                      header.column.id === 'createdAt' && 'text-right',
                    )}
                  >
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="py-3">
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={table.getVisibleLeafColumns().length}
                  className="h-32 text-center"
                >
                  <p className="text-muted-foreground">
                    No deployments match these filters.
                  </p>
                  <Button
                    type="button"
                    variant="link"
                    size="sm"
                    onClick={clearAll}
                  >
                    Reset filters
                  </Button>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      {filteredCount > pageSize && (
        <div className="flex items-center justify-end gap-2">
          <p className="mr-auto text-sm text-muted-foreground tabular-nums">
            {pageIndex * pageSize + 1}–
            {Math.min((pageIndex + 1) * pageSize, filteredCount)} of{' '}
            {filteredCount}
          </p>
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            aria-label="Previous page"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="size-8"
            aria-label="Next page"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
      )}
    </div>
  )
}

import { columns } from './columns'
import { DeploymentsTable } from './data-table'
import { deployments } from './data'

export function DeploymentsDemo() {
  return <DeploymentsTable columns={columns} data={deployments} />
}
